#include <stdio.h>
#include <string.h>
#include <ctype.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    /* Length limit: 0x400 (1024) characters, as observed in the binary */
    if (strlen(s1) >= 0x401 || strlen(s2) >= 0x401) {
        puts("TOO_LONG");
        return 0;
    }
    int freq1[256] = {0};
    int freq2[256] = {0};
    /* Count characters of first string, ignoring spaces and case‑insensitive for A‑Z */
    for (size_t i = 0; s1[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s1[i];
        if (c == ' ') continue;               // ignore spaces
        if ('A' <= c && c <= 'Z') c = c + ('a' - 'A'); // tolower for ASCII letters
        freq1[c]++;
    }
    /* Count characters of second string */
    for (size_t i = 0; s2[i] != '\0'; ++i) {
        unsigned char c = (unsigned char)s2[i];
        if (c == ' ') continue;
        if ('A' <= c && c <= 'Z') c = c + ('a' - 'A');
        freq2[c]++;
    }
    int same = 1;
    for (int i = 0; i < 256; ++i) {
        if (freq1[i] != freq2[i]) { same = 0; break; }
    }
    puts(same ? "ANAGRAM" : "NOT_ANAGRAM");
    return 0;
}
